for h in ath-ms-7a72 ath-ms-7a73; do
  echo "================ $h ================"
  ssh -o BatchMode=yes -o ConnectTimeout=4 -o StrictHostKeyChecking=accept-new "$h" '
    echo "[whoami] $(whoami)@$(hostname)";
    echo "[docker] $(command -v docker || echo none)";
    echo "[podman] $(command -v podman || echo none)";
    echo "[nvidia-smi] $(command -v nvidia-smi || echo none)";
    echo "[sudo-nopass]"; sudo -n true 2>&1 && echo "  sudo OK (nopass)" || echo "  no passwordless sudo";
  ' 2>&1
done

for h in ath-ms-7a72 ath-ms-7a73; do
  echo "================ $h ================"
  ssh -o BatchMode=yes -o ConnectTimeout=4 "$h" '
    echo "[groups] $(groups | tr " " ",")";
    echo "[docker-noroot]"; docker ps >/dev/null 2>&1 && echo "  docker works WITHOUT sudo" || echo "  docker needs sudo / not permitted";
    echo "[gpu]"; nvidia-smi --query-gpu=name,memory.total --format=csv,noheader 2>&1 | head;
    echo "[nvidia-ctk] $(command -v nvidia-ctk || echo none)";
    echo "[docker-nvidia-runtime]"; docker info 2>/dev/null | grep -i runtime || echo "  (docker info needs sudo)";
  ' 2>&1
done

for h in ath-ms-7a72 ath-ms-7a73; do
  echo "================ $h ================"
  ssh -o BatchMode=yes -o ConnectTimeout=5 "$h" '
    echo "--- containers (all) ---"; docker ps -a --format "{{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}" 2>&1;
    echo "--- images ---"; docker images --format "{{.Repository}}:{{.Tag}}\t{{.Size}}" 2>&1 | grep -iE "llama|ollama|cuda|vllm" ;
    echo "--- native ollama ---"; command -v ollama && (systemctl is-active ollama 2>/dev/null; curl -s --max-time 3 http://localhost:11434/api/version 2>&1);
    echo "--- listening 11434/8080/8000 ---"; ss -tlnp 2>/dev/null | grep -E ":11434|:8080|:8000|:8081" || echo none;
  ' 2>&1
done

echo "############ 7a72 (P4000, has nvidia runtime) ############"
ssh -o BatchMode=yes -o ConnectTimeout=6 ath-ms-7a72 '
  echo "--- GPU-in-container test ---"; timeout 60 docker run --rm --gpus all nvidia/cuda:12.2.0-base-ubuntu22.04 nvidia-smi --query-gpu=name --format=csv,noheader 2>&1 | tail -3;
  echo "--- model dirs ---"; sudo -n ls /usr/share/ollama/.ollama/models/blobs 2>/dev/null | wc -l; ls -la ~/.ollama/models/blobs 2>/dev/null | wc -l; du -sh /usr/share/ollama/.ollama 2>/dev/null;
  echo "--- disk ---"; df -h / | tail -1;
  echo "--- ollama models ---"; ollama list 2>&1 | head;
' 2>&1
echo
echo "############ 7a73 (GTX1060 Pascal, NO nvidia runtime) ############"
ssh -o BatchMode=yes -o ConnectTimeout=6 ath-ms-7a73 '
  echo "--- disk ---"; df -h / | tail -1;
  echo "--- ollama models ---"; ollama list 2>&1 | head;
  echo "--- model dir size ---"; du -sh /usr/share/ollama/.ollama 2>/dev/null; ls /usr/share/ollama/.ollama/models/blobs 2>/dev/null | wc -l;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  echo "--- can ath read model dir? ---";
  ls -ld /usr/share/ollama /usr/share/ollama/.ollama /usr/share/ollama/.ollama/models 2>&1;
  echo "--- manifest for vibethinker-q4km ---";
  find /usr/share/ollama/.ollama/models/manifests -iname "*vibethinker-q4km*" 2>&1;
  MAN=$(find /usr/share/ollama/.ollama/models/manifests -path "*vibethinker-q4km*" -type f 2>/dev/null | head -1);
  echo "manifest=$MAN";
  if [ -n "$MAN" ]; then
    echo "--- model layer digest ---";
    grep -o "\"mediaType\":\"application/vnd.ollama.image.model\"[^}]*\"digest\":\"sha256:[a-f0-9]*\"" "$MAN" 2>&1 || cat "$MAN" | python3 -c "import sys,json; d=json.load(sys.stdin); [print(l[\"mediaType\"], l[\"digest\"], l[\"size\"]) for l in d[\"layers\"]]" 2>&1;
  fi;
  echo "--- can ath read a blob? ---";
  ls -l /usr/share/ollama/.ollama/models/blobs 2>&1 | head -3;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  echo "--- ath can read blob? ---";
  head -c 8 /usr/share/ollama/.ollama/models/blobs/sha256-9782b918cc220fb81d59e21be3e45c3ae027e5d86fb56ce7c6d537a347c80d79 | xxd | head -1;
  echo "--- start ollama bench container on :11435 (models ro) ---";
  docker rm -f bench-ollama >/dev/null 2>&1;
  docker run -d --name bench-ollama --gpus all -p 11435:11434 \
    -e OLLAMA_MODELS=/models -e OLLAMA_FLASH_ATTENTION=1 \
    -v /usr/share/ollama/.ollama/models:/models:ro \
    ollama/ollama:latest 2>&1;
  sleep 4;
  echo "--- container status ---"; docker ps --filter name=bench-ollama --format "{{.Status}}";
  echo "--- version + model visible? ---";
  curl -s --max-time 5 http://localhost:11435/api/version;
  echo; curl -s --max-time 5 http://localhost:11435/api/tags | python3 -c "import sys,json;print([m[\"name\"] for m in json.load(sys.stdin)[\"models\"]])" 2>&1 | head -1;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  nohup bash -c "
    docker pull ollama/ollama:latest > /tmp/pull-ollama.log 2>&1;
    docker pull ghcr.io/ggml-org/llama.cpp:server-cuda > /tmp/pull-llamacpp.log 2>&1;
    echo DONE >> /tmp/pull-llamacpp.log
  " >/dev/null 2>&1 &
  echo "pulls started in background";
' 2>&1

BLOB=sha256-9782b918cc220fb81d59e21be3e45c3ae027e5d86fb56ce7c6d537a347c80d79
ssh -o BatchMode=yes ath-ms-7a72 "
  echo '--- recreate ollama on fresh image ---';
  docker rm -f bench-ollama >/dev/null 2>&1;
  docker run -d --name bench-ollama --gpus all -p 11435:11434 \
    -e OLLAMA_MODELS=/models -e OLLAMA_FLASH_ATTENTION=1 \
    -v /usr/share/ollama/.ollama/models:/models:ro \
    ollama/ollama:latest >/dev/null 2>&1 && echo ollama-up;
  echo '--- start llama.cpp server :8081 ---';
  docker rm -f bench-llamacpp >/dev/null 2>&1;
  docker run -d --name bench-llamacpp --gpus all -p 8081:8080 \
    -v /usr/share/ollama/.ollama/models/blobs:/blobs:ro \
    ghcr.io/ggml-org/llama.cpp:server-cuda \
    -m /blobs/$BLOB -ngl 99 -c 4096 -fa on --host 0.0.0.0 --port 8080 >/dev/null 2>&1 && echo llamacpp-started;
  sleep 8;
  echo '--- status ---'; docker ps -a --filter name=bench- --format '{{.Names}} :: {{.Status}}';
  echo '--- ollama version ---'; curl -s --max-time 5 http://localhost:11435/api/version;
  echo; echo '--- llama.cpp health ---'; curl -s --max-time 5 http://localhost:8081/health || echo 'not-ready';
  echo; echo '--- llama.cpp last log ---'; docker logs --tail 6 bench-llamacpp 2>&1 | tail -6;
" 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  for i in $(seq 1 20); do
    h=$(curl -s --max-time 3 http://localhost:8081/health);
    echo "$h" | grep -q "\"status\":\"ok\"" && { echo "llama.cpp READY"; break; }
    sleep 3;
  done
  echo "=== RUNNING BENCHMARK (VibeThinker-3B Q4_K_M, 200 tok greedy) ===";
  bash ~/bench.sh 2>&1;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  MAN=$(find /usr/share/ollama/.ollama/models/manifests -path "*qwen2.5*7b-instruct*" -type f | head -1);
  echo "manifest=$MAN";
  python3 -c "import json;d=json.load(open(\"$MAN\"));[print(l[\"mediaType\"].split(\".\")[-1], l[\"digest\"]) for l in d[\"layers\"]]";
' 2>&1

