VBLOB=sha256-9782b918cc220fb81d59e21be3e45c3ae027e5d86fb56ce7c6d537a347c80d79
ssh -o BatchMode=yes ath-ms-7a72 "
  echo '=== A) ollama CONTAINER (:11435) serving fixed VibeThinker ===';
  curl -s --max-time 90 http://localhost:11435/api/chat -d '{\"model\":\"vibethinker-q4km\",\"messages\":[{\"role\":\"user\",\"content\":\"What is 17*23? Reason step by step.\"}],\"stream\":false,\"options\":{\"num_predict\":400}}' \
  | python3 -c 'import sys,json;d=json.load(sys.stdin);print(\"eval_count=\",d.get(\"eval_count\"),\"| decode tok/s=\",round(d.get(\"eval_count\",0)/(d.get(\"eval_duration\",1)or 1)*1e9,2),\"| done=\",d.get(\"done_reason\"));print(\"has <think>:\", \"<think>\" in d.get(\"message\",{}).get(\"content\",\"\"))';
  echo;
  echo '=== B) (re)start llama.cpp CONTAINER (:8081) with VibeThinker + --jinja chat template ===';
  docker rm -f bench-llamacpp >/dev/null 2>&1;
  docker run -d --name bench-llamacpp --gpus all -p 8081:8080 \
    -v /usr/share/ollama/.ollama/models/blobs:/blobs:ro \
    ghcr.io/ggml-org/llama.cpp:server-cuda \
    -m /blobs/$VBLOB -ngl 99 -c 16384 -fa on --jinja --host 0.0.0.0 --port 8080 >/dev/null 2>&1 && echo started;
  for i in \$(seq 1 25); do curl -s --max-time 3 http://localhost:8081/health 2>/dev/null | grep -q '\"status\":\"ok\"' && { echo READY; break; }; sleep 3; done;
" 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  echo "=== container status ==="; docker ps --filter name=bench- --format "{{.Names}} :: {{.Status}}";
  echo "=== ollama container: does it see the model? ==="; curl -s --max-time 5 http://localhost:11435/api/tags | python3 -c "import sys,json;print([m[\"name\"] for m in json.load(sys.stdin).get(\"models\",[])][:5])" 2>&1;
  echo "=== ollama container chat (verbose) ==="; curl -s -w "\nHTTP=%{http_code}\n" --max-time 90 http://localhost:11435/api/chat -d "{\"model\":\"vibethinker-q4km\",\"messages\":[{\"role\":\"user\",\"content\":\"What is 17*23?\"}],\"stream\":false,\"options\":{\"num_predict\":300}}" 2>&1 | tail -c 400;
  echo; echo "=== ollama container recent logs ==="; docker logs --tail 8 bench-ollama 2>&1 | tail -8;
  echo "=== llama.cpp health + logs ==="; curl -s --max-time 4 http://localhost:8081/health; echo; docker logs --tail 5 bench-llamacpp 2>&1 | tail -5;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  echo "=== GPU residents now ==="; nvidia-smi --query-compute-apps=pid,used_memory,process_name --format=csv,noheader 2>&1;
  echo "=== free mem ==="; nvidia-smi --query-gpu=memory.used,memory.free,memory.total --format=csv,noheader;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  docker stop bench-llamacpp >/dev/null 2>&1; echo "llama.cpp stopped, GPU freed";
  # nudge native ollama to unload anything it is holding
  curl -s http://localhost:11434/api/generate -d "{\"model\":\"vibethinker-q4km\",\"keep_alive\":0,\"prompt\":\"\"}" >/dev/null 2>&1;
  sleep 2;
  echo "############ OLLAMA container (:11435) — VibeThinker ############";
  for r in 1 2 3; do
    curl -s --max-time 120 http://localhost:11435/api/chat -d "{\"model\":\"vibethinker-q4km\",\"messages\":[{\"role\":\"user\",\"content\":\"What is 17*23? Reason step by step.\"}],\"stream\":false,\"options\":{\"num_predict\":300}}" \
    | python3 -c "import sys,json;d=json.load(sys.stdin);print(\"  run$r: gen %d tok @ %.2f tok/s | done=%s\"%(d.get(\"eval_count\",0),d.get(\"eval_count\",0)/(d.get(\"eval_duration\",1)or 1)*1e9,d.get(\"done_reason\")))" 2>&1 || echo "  run$r failed";
    if [ $r -eq 1 ]; then echo "  [GPU residents]"; nvidia-smi --query-compute-apps=pid,used_memory,process_name --format=csv,noheader | sed "s/^/    /"; fi
  done
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  echo "=== is GPU visible INSIDE the ollama container? ===";
  docker exec bench-ollama nvidia-smi --query-gpu=name --format=csv,noheader 2>&1 | head -3;
  echo "=== ollama container GPU-detection logs ===";
  docker logs bench-ollama 2>&1 | grep -iE "gpu|nvidia|cuda|library|inference compute|no compatible|rocm|cpu" | head -20;
' 2>&1

ssh -o BatchMode=yes ath-ms-7a72 '
  docker stop bench-llamacpp >/dev/null 2>&1;
  curl -s http://localhost:11434/api/generate -d "{\"model\":\"vibethinker-q4km\",\"keep_alive\":0,\"prompt\":\"\"}" >/dev/null 2>&1;
  docker restart bench-ollama >/dev/null 2>&1; echo "ollama container restarted, waiting for ready...";
  for i in $(seq 1 20); do curl -s --max-time 3 http://localhost:11435/api/version >/dev/null 2>&1 && break; sleep 2; done;
  sleep 3; echo "GPU free before: $(nvidia-smi --query-gpu=memory.free --format=csv,noheader)";
  # fire a generation in background, sample GPU mid-flight
  ( curl -s --max-time 120 http://localhost:11435/api/chat -d "{\"model\":\"vibethinker-q4km\",\"messages\":[{\"role\":\"user\",\"content\":\"What is 17*23? Reason step by step.\"}],\"stream\":false,\"options\":{\"num_predict\":300}}" > /tmp/ollama_run.json ) &
  CPID=$!;
  sleep 12; echo "=== GPU residents DURING generation ==="; nvidia-smi --query-compute-apps=pid,used_memory,process_name --format=csv,noheader;
  wait $CPID;
  python3 -c "import json;d=json.load(open(\"/tmp/ollama_run.json\"));print(\"RESULT: gen %d tok @ %.2f tok/s | done=%s\"%(d.get(\"eval_count\",0),d.get(\"eval_count\",0)/(d.get(\"eval_duration\",1)or 1)*1e9,d.get(\"done_reason\")))";
  echo "=== fresh load backend ==="; docker logs bench-ollama 2>&1 | grep -iE "offloaded|skipping CUDA|inference compute|CPU model buffer|layers to GPU" | tail -4;
' 2>&1

for h in ath-ms-7a72 ath-ms-7a73; do
  echo "================= $h ================="
  ssh -o BatchMode=yes "$h" '
    echo "[container] $(docker ps --filter name=vibethinker --format "{{.Status}} | restart-policy:" )$(docker inspect -f "{{.HostConfig.RestartPolicy.Name}}" vibethinker)";
    echo "[listening] $(ss -tlnp 2>/dev/null | grep -c ":8080 ") socket on :8080";
    echo "[gpu-resident] $(nvidia-smi --query-compute-apps=used_memory,process_name --format=csv,noheader | grep -i llama-server | head -1)";
    echo "[native ollama vibethinker id] $(ollama list | awk "/vibethinker-q4km/{print \$1}")";
    # tidy scratch bench files, keep deploy script + Modelfile
    rm -f ~/bench.sh ~/bench-qwen.sh 2>/dev/null;
  ' 2>&1
done
echo "=== quick cross-machine reachability from lil-blue ==="
for ip in 192.168.1.8 192.168.1.15; do echo -n "$ip:8080 -> "; curl -s --max-time 5 http://$ip:8080/health || echo unreachable; echo; done
